import type { Telemetry, TelemetryProperties } from './types'
import { NoOpTelemetry } from './clients/noop-client'

function implementsTelemetry(candidate: unknown): candidate is Telemetry {
    if (!candidate || typeof candidate !== 'object') {
        return false
    }
    const client = candidate as Record<string, unknown>
    return (
        typeof client['capture'] === 'function' &&
        typeof client['captureError'] === 'function' &&
        typeof client['flush'] === 'function' &&
        typeof client['shutdown'] === 'function'
    )
}

// Pre-AppSee->PostHog-migration client shape (sendEvent/error/startTimerEvent). An embedder
// on an older SDK can still build one of these and hand it to a newer Project/Orchestrator.
type LegacyTelemetry = {
    sendEvent(eventData: {
        name: string
        appInfo?: { scopeId?: string } | undefined
        data?: Record<string, unknown> | undefined
    }): void
    error(event: string, error: unknown, data?: Record<string, unknown> | undefined): void
}

function implementsLegacyTelemetry(candidate: unknown): candidate is LegacyTelemetry {
    if (!candidate || typeof candidate !== 'object') {
        return false
    }
    const client = candidate as Record<string, unknown>
    return typeof client['sendEvent'] === 'function' && typeof client['error'] === 'function'
}

// Adapts a legacy client to the current interface so events still reach its backend instead
// of being dropped. flush/shutdown have no legacy equivalent (each event was fire-and-forget)
// so they're safe no-ops.
class LegacyTelemetryAdapter implements Telemetry {
    constructor(private readonly legacy: LegacyTelemetry) {}

    capture(event: string, properties?: TelemetryProperties): void {
        // Legacy events keyed scope via appInfo.scopeId; pull it back out of properties.scope_id.
        const scopeId = properties?.['scope_id']
        const appInfo = typeof scopeId === 'string' ? { scopeId } : undefined
        this.legacy.sendEvent({ name: event, appInfo, data: properties })
    }

    captureError(event: string, error: unknown, properties?: TelemetryProperties): void {
        this.legacy.error(event, error, properties)
    }

    async flush(): Promise<void> {}

    async shutdown(): Promise<void> {}
}

// A client built by a different SDK version than the Project/Orchestrator it's handed to may
// not implement the methods called on it. Telemetry must never crash a build: current-interface
// clients pass through, legacy-shaped clients get adapted, anything else falls back to a no-op.
export function toSafeTelemetry(client: Telemetry | undefined): Telemetry | undefined {
    if (client === undefined) {
        return undefined
    }
    if (implementsTelemetry(client)) {
        return client
    }
    if (implementsLegacyTelemetry(client)) {
        return new LegacyTelemetryAdapter(client)
    }
    return new NoOpTelemetry()
}
